NAME = 'SloKJV: Slovenian translation of Holy Bible King James Version (1769)'
BOOK = 'Zephaniah'

CHAPTERS = {
    1: {
        1: 'Gospodova beseda, ki je prišla Sofoniju, sinu Kušíja, sinú Gedaljája, sinú Amarjá, sinú Hezekija, v dneh Jošíja, Amónovega sina, Judovega kralja.',
        2: '»Popolnoma bom použil vse stvari iz dežele,« govori Gospod.',
        3: '»Použil bom človeka in žival. Z zlobnimi bom použil perjad neba in ribe morja in kamne spotike in človeka bom iztrebil iz dežele,« govori Gospod.',
        4: '»Prav tako bom svojo roko iztegnil nad Juda in nad vse prebivalce Jeruzalema in iztrebil bom preostanek Báala iz tega mesta in ime Kemarimov z duhovniki;',
        5: 'in tiste, ki obožujejo vojsko neba na hišnih strehah; in tiste, ki obožujejo in ki prisegajo pri Gospodu in prisegajo pri Milkómu;',
        6: 'in tiste, ki so obrnjeni nazaj od Gospoda; in tiste, ki niso iskali Gospoda niti poizvedovali za njim.«',
        7: 'Mirujte ob prisotnosti Gospoda Boga, kajti dan Gospodov je pri roki, kajti Gospod je pripravil klavno daritev, povabil je svoje goste.',
        8: '»In zgodilo se bo, na dan Gospodove klavne daritve, da bom kaznoval prince in kraljeve otroke in vse tiste, ki so oblečeni s tujo obleko.',
        9: 'V istem dnevu bom kaznoval tudi vse tiste, ki poskakujejo na pragu, ki napolnjujejo hiše svojih gospodarjev z nasiljem in prevaro.',
        10: 'Na tisti dan se bo zgodilo,« govori Gospod, » da bo glas vpitja od Ribjih velikih vrat in tuljenja od drugih in veliko lomljenje s hribov.',
        11: 'Tulite, vi prebivalci Maltarke, kajti vse trgovsko ljudstvo je posekano. Vsi tisti, ki nosijo srebro, so iztrebljeni.',
        12: 'Ob tistem času se bo zgodilo, da bom Jeruzalem preiskal s svetilkami in kaznoval ljudi, ki so naseljeni na svojih usedlinah, ki v svojem srcu pravijo: › Gospod ne bo storil dobrega niti ne bo storil zlega.‹',
        13: 'Zato bodo njihove dobrine postale plen in njihove hiše opustošenje. Prav tako bodo gradili hiše, toda ne bodo jih poselili in sadili bodo vinograde, toda od njihovega vina ne bodo pili.«',
        14: 'Gospodov véliki dan je blizu, ta je blizu in silno hiti, celó glas Gospodovega dneva. Mogočen človek bo tam grenko jokal.',
        15: 'Tisti dan je dan besa, dan stiske in tegobe, dan pustote in opustošenja in dan teme in mračnosti, dan oblakov in goste teme,',
        16: 'dan šofarja in alarma zoper utrjena mesta in zoper visoke stolpe.',
        17: '»Na ljudi bom privedel tegobo, da bodo hodili kakor slepi ljudje, ker so grešili zoper Gospoda in njihova kri bo izlita kakor prah in njihovo meso kakor gnoj.«',
        18: 'Niti jih njihovo srebro niti njihovo zlato ne bo moglo osvoboditi na dan Gospodovega besa, temveč bo celotna dežela použita z ognjem njegove ljubosumnosti, kajti celo zelo hitro se bo znebil vseh tistih, ki prebivajo v deželi.«',
    },
    2: {
        1: 'Zberite se skupaj, da, zberite se skupaj, oh narod, ki ni zaželen.',
        2: 'Preden se rodi odlok, preden dan mine kakor pleve, preden pride nad vas kruta Gospodova jeza, preden pride nad vas dan Gospodove jeze.',
        3: 'Iščite Gospoda, vsi vi krotki na zemlji, ki ste vršili njegovo sodbo, iščite pravičnost, iščite krotkost. Morda bo, da boste skriti na dan Gospodove jeze.',
        4: 'Kajti Gaza bo zapuščena in Aškelón opustošenje. Ašdód bodo izgnali opoldan in Ekrón bo izkoreninjen.',
        5: 'Gorje prebivalcem morske obale, narodu Keretéjcev! Gospodova beseda je zoper tebe, oh Kánaan, dežela Filistejcev, celo uničil te bom, da tam ne bo nobenega prebivalca.',
        6: 'Morska obala bodo pašniki in koče za pastirje in staje za trope.',
        7: 'Obala bo za preostanek Judove hiše. Pasli se bodo na njej. V aškelónskih hišah bodo zvečer legli, kajti Gospod, njihov Bog, jih bo obiskal in odvrnil njihovo ujetništvo.',
        8: '»Slišal sem grajo Moába in zasramovanja Amónovih otrok, s katerimi so grajali moje ljudstvo in se poveličevali zoper njihovo mejo.',
        9: 'Zato kakor jaz živim,« govori Gospod nad bojevniki, Izraelov Bog: »Zagotovo bo Moáb kakor Sódoma in Amónovi otroci kakor Gomóra, celó gojenje kopriv in solne jame in nenehno opustošenje. Preostanek mojega ljudstva jih bo oplenil in preostanek mojega ljudstva jih bo vzel v last.«',
        10: 'To bodo imeli zaradi svojega ponosa, ker so grajali in se poveličevali zoper ljudstvo Gospoda nad bojevniki.',
        11: 'Gospod jim bo strašen, kajti izstradal bo vse bogove zemlje in ljudje ga bodo oboževali, vsak iz svojega kraja, celó vsi otoki poganov.',
        12: '»Tudi vi Etiopijci boste umorjeni z mojim mečem.«',
        13: 'Svojo roko bo iztegnil zoper sever in uničil Asirijo in Ninive bo naredil opustošenje in suho kakor divjina.',
        14: 'Tropi se bodo ulegli v njegovi sredi, vse živali narodov, tako kormoran kot bobnarica bosta prenočevala v njegovih zgornjih prekladah. Njihov glas bo prepeval na oknih, opustošenje bo na pragih, kajti odkril bo cedrovo oblogo.',
        15: 'To je veseleče se mesto, ki je brezskrbno prebivalo, ki je v svojem srcu govorilo: ›Jaz sem in poleg mene ni nikogar.‹ Kako je postalo opustošenje, kraj za živali, da se uležejo v njem! Vsak, kdor gre mimo njega, ga bo izžvižgal in zamahnil s svojo roko.«',
    },
    3: {
        1: 'Gorje njej, ki je umazana in oskrunjena, zatiralskemu mestu, [prestolnici Jeruzalem]!',
        2: 'Ni ubogala glasu, ni sprejela grajanja, ni zaupala v Gospoda, ni se približala k svojemu Bogu.',
        3: 'Njeni princi znotraj nje so rjoveči levi; njeni sodniki so večerni volkovi; kosti ne zgrizejo do naslednjega dne.',
        4: 'Njeni preroki so nepomembni in zahrbtne osebe, njeni duhovniki so oskrunili svetišče, postavi so storili nasilje.',
        5: 'Pravičen Gospod je v njeni sredi. Ne bo storil krivičnosti, vsako jutro svojo sodbo prinaša na svetlo, ne odpove. Toda krivičnik ne pozna sramu.',
        6: '»Iztrebil sem narode; njihovi stolpi so zapuščeni, njihove ulice sem naredil opustošene, da nihče ne hodi mimo. Njihova mesta so uničena, tako da tam ni nobenega človeka, da tam ni nobenega prebivalca.',
        7: 'Rekel sem: ›Zagotovo se me boš bala, prejela boš poučevanje.‹ Tako njihova prebivališča ne bi smela biti iztrebljena, vendar sem jih kaznoval; vendar so vstali zgodaj in izpridili vsa svoja početja.',
        8: 'Zatorej čakajte name,« govori Gospod, »do dneva, ko se dvignem k plenu, kajti moja odločitev je, da zberem narode, da lahko zberem kraljestva, da nanje izlijem svoje ogorčenje, celó vso svojo kruto jezo, kajti vsa zemlja bo požrta z ognjem moje ljubosumnosti.',
        9: 'Kajti takrat se bom obrnil k ljudstvu čistega jezika, da bodo lahko vsi klicali h Gospodovemu imenu, da mu soglasno služijo.',
        10: 'Iz druge strani reke Etiopije mi bodo slavilci, celó hči mojih razkropljencev, prinesli mojo daritev.',
        11: 'Na tisti dan ne boš osramočena zaradi vseh svojih početij, s katerimi si se prekršila zoper mene, kajti takrat bom iz tvoje srede odvedel vse tiste, ki se veselijo v tvojem ponosu in ne boš več ošabna zaradi moje svete gore.',
        12: 'Prav tako bom v tvoji sredi pustil trpeče in ubogo ljudstvo in ti bodo zaupali v Gospodovo ime.',
        13: 'Izraelov preostanek ne bo počel krivičnosti niti govoril laži niti v njihovih ustih ne bo najden varljiv jezik, kajti pasli se bodo in se zleknili in nihče jih ne bo strašil.',
        14: 'Prepevaj, oh hči sionska; vzklikaj, oh Izrael; bodi vesela in razveseljuj se z vsem srcem, oh hči jeruzalemska.',
        15: 'Gospod je odvzel tvoje obsodbe, pregnal tvojega sovražnika. Izraelov kralj, celó Gospod, je v tvoji sredi. Nobenega zla ne boš več videla.',
        16: 'Na tisti dan bo [prestolnici] Jeruzalem rečeno: ›Ne boj se.‹ in Sionu: ›Ne dopusti, da bi bile tvoje roke mlahave.‹',
        17: 'Gospod, tvoj Bog, v tvoji sredi je mogočen. Rešil bo, z radostjo se bo veselil nad teboj, počival bo v svoji ljubezni, nad teboj se bo veselil s prepevanjem.',
        18: 'Zbral bom tiste, ki žalujejo po slovesnem zboru, ki so iz tebe, ki jim je bila ta sramota breme.',
        19: 'Glej, ob tistem času bom odstranil vse tiste, ki te stiskajo in rešil bom tisto, kar šepa in zbral tisto, kar je bilo izgnano in dal jim bom hvalo in sloves v vsaki deželi, kjer so bili osramočeni.',
        20: 'Ob tistem času vas bom ponovno privedel, celo v času, ko vas zberem, kajti naredil vas bom za ime in hvalo med vsemi narodi zemlje, ko pred vašimi očmi obrnem vaše ujetništvo nazaj,‹ govori Gospod.«',
    },
}
